import { z } from 'zod';
import { isValidTimezone } from '../timezone';

export const uuidSchema = z.uuid();

/** A UUID generated by the client for a create, so a retry returns the same row (Agent rule 14). */
export const clientIdSchema = z.uuid();

/** UTC ISO 8601 timestamp with offset, as sent by the API. */
export const isoDateTimeSchema = z.iso.datetime({ offset: true });

export const timezoneSchema = z.string().refine(isValidTimezone, {
  message: 'Unknown time zone. Use an IANA name such as Africa/Accra.',
});

export const httpsUrlSchema = z.url({
  protocol: /^https$/,
  message: 'Enter the full link, starting with https://',
});

/** Parameters of routes like /users/{id}. */
export const idParamsSchema = z.object({ id: uuidSchema });
